using Microsoft.EntityFrameworkCore;
class AppDbContext : DbContext
{
    public DbSet<Order> Orders => Set<Order>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: HasData no longer accepts navigation values inline.
        // Use fixed seed data (not DateTime.UtcNow) to avoid generating a new migration on every run.
        modelBuilder.Entity<Order>().HasData(
            new Order { Id = 1, CreatedAt = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc) });
    }
}
class Order { public int Id { get; set; } public DateTime CreatedAt { get; set; } }

// --- Cosmos DB context demonstrating EF Core 9 breaking-change fixes ---
class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        optionsBuilder.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            databaseName: "Shop");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(b =>
        {
            b.ToContainer("Products");
            b.HasPartitionKey(p => p.Category);
            b.HasNoDiscriminator();

            // EF Core 9 breaking change: Cosmos provider now uses '$type' as the default
            // discriminator property name instead of 'Discriminator'.
            // For existing documents that already store "Discriminator", explicitly configure it:
            b.HasDiscriminator<string>("Discriminator");
        });
    }

    // EF Core 9 breaking change: Synchronous I/O on Cosmos provider now throws by default.
    // All queries/saves must use async methods.
    public async Task<List<Product>> GetProductsAsync(string category)
    {
        // BEFORE (EF Core 8 allowed sync): Products.Where(...).ToList();
        // AFTER  (EF Core 9 requires async):
        return await Products.Where(p => p.Category == category).ToListAsync();
    }

    public async Task SaveProductAsync(Product product)
    {
        Products.Add(product);
        // BEFORE: SaveChanges();
        // AFTER:
        await SaveChangesAsync();
    }
}

class Product
{
    public string Id { get; set; } = Guid.NewGuid().ToString();
    public string Name { get; set; } = "";
    public string Category { get; set; } = "";
}

