using Microsoft.EntityFrameworkCore;
class MigrationRunner
{
    // EF Core 9 breaking change: Migrate() can no longer be called inside a manual
    // transaction. It now manages its own transaction internally.
    void ApplyMigrations(AppDbContext db)
    {
        var strategy = db.Database.CreateExecutionStrategy();
        strategy.Execute(() =>
        {
            // Removed BeginTransaction()/Commit() wrapper – EF Core 9 throws
            // if Migrate() is called within a user-supplied transaction.
            db.Database.Migrate();
        });
    }
}

